/**
 * parse-figma-vines.cjs — 解析Figma矢量路径，转世界坐标
 */

// Figma坐标系
// 脊柱中心线: abs x=5, topY=-656, botY=668.5, height=1324.5
// Vine1(green): abs offset (-154, -665.5)
// Vine2(blue): abs offset (-149.5, -598.5)

const SPINE_X = 5;
const SPINE_TOP_Y = -656;
const SPINE_BOT_Y = 668.5;
const SPINE_HEIGHT = SPINE_BOT_Y - SPINE_TOP_Y; // 1324.5
const WORLD_TOP = 2.36;
const WORLD_BOT = -2.36;
const PX_PER_WORLD = SPINE_HEIGHT / (WORLD_TOP - WORLD_BOT);

function toWorld(absX, absY) {
  const wx = (absX - SPINE_X) / Math.abs(PX_PER_WORLD);
  const wy = WORLD_TOP - (absY - SPINE_TOP_Y) / Math.abs(PX_PER_WORLD);
  return [parseFloat(wx.toFixed(4)), parseFloat(wy.toFixed(4))];
}

function cubicBezier(p0, p1, p2, p3, t) {
  const u = 1 - t;
  return [
    u*u*u*p0[0] + 3*u*u*t*p1[0] + 3*u*t*t*p2[0] + t*t*t*p3[0],
    u*u*u*p0[1] + 3*u*u*t*p1[1] + 3*u*t*t*p2[1] + t*t*t*p3[1]
  ];
}

// Parse SVG path d string into segments (split by M commands)
function parsePath(d, offX, offY) {
  const segments = [];
  let current = [];
  let cx = 0, cy = 0;

  const tokens = d.match(/[MC]|[-+]?\d*\.?\d+/g);
  if (!tokens) return segments;

  let i = 0;
  while (i < tokens.length) {
    const tok = tokens[i];
    if (tok === 'M') {
      i++;
      // New segment starts
      if (current.length >= 2) segments.push(current);
      const x = parseFloat(tokens[i++]);
      const y = parseFloat(tokens[i++]);
      cx = x; cy = y;
      current = [[x + offX, y + offY]];
    } else if (tok === 'C') {
      i++;
      const x1 = parseFloat(tokens[i++]), y1 = parseFloat(tokens[i++]);
      const x2 = parseFloat(tokens[i++]), y2 = parseFloat(tokens[i++]);
      const x3 = parseFloat(tokens[i++]), y3 = parseFloat(tokens[i++]);
      // Sample bezier at intervals
      const steps = 8;
      for (let s = 1; s <= steps; s++) {
        const t = s / steps;
        const pt = cubicBezier([cx + offX, cy + offY], [x1 + offX, y1 + offY], [x2 + offX, y2 + offY], [x3 + offX, y3 + offY], t);
        current.push(pt);
      }
      cx = x3; cy = y3;
    } else {
      i++; // skip unknown
    }
  }
  if (current.length >= 2) segments.push(current);
  return segments;
}

// Convert all segments to world coords
function toWorldSegments(segments) {
  return segments.map(seg => seg.map(([x, y]) => toWorld(x, y)));
}

