// Output as JS
const fs = require('fs');
function formatSegs(segs) {
  return segs.map((seg, i) => {
    const pts = seg.map(([x,y]) => `[${x},${y}]`).join(',');
    return `  [${pts}]`;
  }).join(',\n');
}

const output = `// Figma矢量路径 → 世界坐标（自动生成）
// Vine1=绿色, Vine2=蓝色
// 每个segment是一段连续可见的藤蔓

export const VINE1_SEGMENTS = [
${formatSegs(vine1Segs)}
];

export const VINE2_SEGMENTS = [
${formatSegs(vine2Segs)}
];
`;

fs.writeFileSync('spine-viz/figma-vine-paths.js', output);
